trait Labelled: std::fmt::Display {
    fn id(&self) -> u32;
}

impl std::fmt::Display for Square {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "square {}", self.side)
    }
}

